+// The side chat is a fork of one main conversation. After /resume or /branch the session id is another one: the open side
+// chat (and a child still answering) is about the conversation it was forked from, so it is ended and the next message
+// forks the one now open. The same id changes nothing.
+async function followMain($: EngineInterface) {
+  const c = await read($, chat)
+  if (c.mainId === null || c.mainId === (await $.session.id())) return
+  await newFork($)
+}
